CREATE TABLE "PayrollLocalJournalReversal" ("id" TEXT NOT NULL,"journalId" TEXT NOT NULL,"lines" JSONB NOT NULL,"totals" JSONB NOT NULL,"reason" TEXT NOT NULL,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PayrollLocalJournalReversal_pkey" PRIMARY KEY ("id"),CONSTRAINT "PayrollLocalJournalReversal_journalId_fkey" FOREIGN KEY ("journalId") REFERENCES "PayrollLocalJournal"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PayrollLocalJournalReversal_journalId_key" ON "PayrollLocalJournalReversal"("journalId");
